"""Self-contained, inert HTML projection of an evidence-review queue."""
from html import escape
import json

from review_rules import PRIORITIES


def render_html(report: dict, demo: bool = False) -> str:
    def pre(value):
        return '<pre>'+escape(json.dumps(value, ensure_ascii=False, indent=2))+'</pre>'

    stats = ''.join('<div class="stat"><strong>'+str(report['summary']['by_priority'].get(code, 0))+'</strong><span>'+escape(label)+'</span></div>' for code, label in PRIORITIES.items())
    items = []
    for item in report['items']:
        steps = ''.join('<li>'+escape(step)+'</li>' for step in item['next_steps'])
        items.append('<article id="'+escape(item['id'], quote=True)+'"><div class="item-head"><span class="badge '+item['priority']+'">'+escape(PRIORITIES[item['priority']])+'</span><span class="rule">'+escape(item['rule_id'])+'</span></div><h3>'+escape(item['title'])+'</h3><p>'+escape(item['reason'])+'</p><h4>Próxima verificação sugerida</h4><ol>'+steps+'</ol><details><summary>Conferir fatos e origem</summary>'+pre({'facts': item['facts'], 'references': item['references']})+'<a href="#sources">Ver arquivos, hashes e cobertura</a></details></article>')
    source_html = ''.join('<details><summary>'+escape(role)+'</summary>'+pre(data)+'</details>' for role, data in report['inputs'].items())
    warnings = '<details><summary>Avisos dos importadores</summary>'+pre(report['warnings'])+'</details>' if report['warnings'] else ''
    limits = ''.join('<li>'+escape(x)+'</li>' for x in report['limitations'])
    notice = '<p class="notice">Demonstração com relatórios sintéticos. Nenhuma coleta ou verificação de rede foi realizada.</p>' if demo else ''
    return '''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
<title>FERRAMENTA-HACKER · plano de revisão</title><style>
:root{color-scheme:dark;--bg:#10141e;--panel:#1b2333;--line:#3b4c63;--text:#f1f5fc;--muted:#c1cbdc;--accent:#8adfd2}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.6 system-ui,sans-serif}main{max-width:1100px;padding:36px 24px;margin:auto}header{border-bottom:1px solid var(--line);padding-bottom:24px}.eyebrow{font-size:.8rem;letter-spacing:.1em;color:var(--accent)}h1{font-size:clamp(1.9rem,5vw,3.4rem);line-height:1.15;margin:.6em 0}h2{margin-top:2em}h3{line-height:1.35;font-size:1.3rem}h4{margin-bottom:.4em}p,li{max-width:90ch}nav{display:flex;gap:24px;flex-wrap:wrap;margin-top:24px}a{color:var(--accent)}a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.muted,.rule{color:var(--muted)}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:16px;margin:28px 0}.stat,article,details,.notice{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:20px}.stat strong{display:block;font-size:2.2rem;color:var(--accent)}.stat span{color:var(--muted)}article{margin:18px 0}.item-head{display:flex;gap:14px;align-items:center;justify-content:space-between;flex-wrap:wrap}.badge{border:1px solid var(--line);border-radius:999px;padding:4px 12px;font-size:.85rem}.review-first{color:#ffddb1;border-color:#b28a55}.review-next{color:#a9dfec}.context{color:var(--muted)}details{margin:12px 0;min-width:0;padding:14px}summary{cursor:pointer;font-weight:600}pre{font-size:.8rem;white-space:pre-wrap;overflow-wrap:anywhere;max-height:32rem;overflow:auto;color:var(--muted)}.scope{padding:14px 18px;border-left:4px solid var(--accent);background:var(--panel)}footer{margin-top:36px;border-top:1px solid var(--line);padding-top:18px;color:var(--muted);font-size:.8rem;overflow-wrap:anywhere}@media print{body{background:white;color:black}main{padding:0}article,details,.notice,.stat,.scope{background:white}.muted,.rule,pre,footer,.stat span{color:#333}a{color:#005c50}.badge{color:black}pre{max-height:none}}
</style></head><body><main><header><div class="eyebrow">FERRAMENTA-HACKER / REVISÃO COM EVIDÊNCIAS</div><h1>Do registro à próxima verificação.</h1>
<p class="muted">Uma fila explicável para revisar diferenças de rede e declarações de vulnerabilidades, com origem e limites visíveis.</p>'''+notice+'''<nav aria-label="Seções"><a href="#queue">Fila de revisão</a><a href="#sources">Fontes</a><a href="#limits">Como interpretar</a></nav></header><section aria-label="Resumo"><div class="stats">'''+stats+'''</div><p class="scope">A prioridade organiza a revisão humana. Ela não confirma risco, explorabilidade ou correspondência entre um IP e um pacote.</p></section><section id="queue"><h2>Fila de revisão</h2>'''+(''.join(items) if items else '<p class="notice">Não há itens nos campos examinados. Isso não comprova segurança ou completude da avaliação.</p>')+'''</section><section id="sources"><h2>Fontes e cobertura</h2>'''+source_html+warnings+'''</section><section id="limits"><h2>Como interpretar</h2><ul>'''+limits+'''</ul><details><summary>Regras e identidade da revisão</summary>'''+pre({'review_id': report['review_id'], 'ruleset': report['ruleset']})+'''</details></section><footer>Relatório offline. Nenhuma sugestão é executada automaticamente. '''+escape(report['review_id'])+'</footer></main></body></html>'
